// OTHVM Expenses Tool — personal expense tracker. No LLM.
const base = String($env.SUPABASE_URL ?? '');
const key = String($env.SUPABASE_SERVICE_KEY ?? '');
const TG = 'REPLACE_WITH_TELEGRAM_BOT_TOKEN';
const CHAT = 'REPLACE_WITH_TELEGRAM_CHAT_ID';
if (!base || !key) return [{ json: { ok: false, error: 'Supabase env vars missing in the n8n environment' } }];
const HB = { apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json', Accept: 'application/json' };
const hreq = async (o) => {
  const opts = Object.assign({ returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 25000 }, o);
  try { return await this.helpers.httpRequest(opts); } catch (e) { return { statusCode: 0, body: 'ERR ' + (e && e.message ? e.message : String(e)) }; }
};
const parse = (r) => { let d = r.body; if (typeof d === 'string' && d.length) { try { d = JSON.parse(d); } catch (e) {} } return { st: r.statusCode ?? 0, d }; };
const errOf = (r) => { const d = r.d; if (d && typeof d === 'object' && (d.message || d.hint)) return String(d.message) + (d.hint ? ' — ' + String(d.hint) : ''); return String(typeof d === 'string' ? d : JSON.stringify(d || '')).slice(0, 240); };
const cairoToday = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const input = $input.first().json || {};
const NAME = (v) => String(v == null ? '' : v).trim();
let op = NAME(input.operation);
if (op.indexOf('expense.') === 0) op = op.slice(8);
const round2 = (n) => Math.round(Number(n || 0) * 100) / 100;
const money = (n) => String(round2(n));
const isDate = (s) => { if (typeof s !== 'string' || s.length !== 10) return false; const p = s.split('-'); if (p.length !== 3) return false; const y = Number(p[0]); const m = Number(p[1]); const d = Number(p[2]); return y > 2000 && m >= 1 && m <= 12 && d >= 1 && d <= 31; };
const weekStartCairo = () => { const t = cairoToday().split('-').map(Number); const dt = new Date(Date.UTC(t[0], t[1] - 1, t[2])); const back = (dt.getUTCDay() + 1) % 7; dt.setUTCDate(dt.getUTCDate() - back); return dt.toISOString().slice(0, 10); };
const monthStartCairo = () => cairoToday().slice(0, 8) + '01';
const sumRows = (rows) => rows.reduce((a, x) => a + Number(x.amount || 0), 0);
const byCat = (rows) => { const m = {}; for (const x of rows) { const c = String(x.category || 'متفرقات'); if (!m[c]) m[c] = { category: c, total: 0, count: 0 }; m[c].total += Number(x.amount || 0); m[c].count += 1; } return Object.keys(m).map((k) => m[k]).sort((a, b) => b.total - a.total); };

try {
  if (op === 'log') {
    const amount = round2(input.amount);
    if (!isFinite(amount) || amount <= 0) return [{ json: { ok: false, error: 'amount لازم يكون رقم أكبر من صفر' } }];
    const category = NAME(input.category) || 'متفرقات';
    const description = NAME(input.description);
    const spentOn = NAME(input.spent_on);
    if (spentOn && !isDate(spentOn)) return [{ json: { ok: false, error: 'spent_on لازم يكون YYYY-MM-DD (اتركه فاضي = النهارده بتوقيت القاهرة)' } }];
    const body = { amount: amount, category: category, description: description, currency: 'EGP' };
    if (spentOn) body.spent_on = spentOn;
    const ins = parse(await hreq({ method: 'POST', url: base + '/rest/v1/expenses', headers: Object.assign({}, HB, { Prefer: 'return=representation' }), body: body, json: true }));
    if (ins.st <= 0 || ins.st >= 300) return [{ json: { ok: false, error: 'فشل تسجيل المصروف: ' + errOf(ins) } }];
    const row = Array.isArray(ins.d) ? ins.d[0] : ins.d;
    const day = spentOn || cairoToday();
    const tr = parse(await hreq({ method: 'GET', url: base + '/rest/v1/expenses?select=amount&spent_on=eq.' + day, headers: HB, json: true }));
    const rows = (tr.st > 0 && tr.st < 300 && Array.isArray(tr.d)) ? tr.d : [row];
    const total = round2(sumRows(rows));
    return [{ json: { ok: true, expense: { id: row.id, amount: amount, category: category, description: description, spent_on: (row && row.spent_on) || day }, today: { date: day, total: total, count: rows.length }, message: '✅ اتسجل: ' + money(amount) + ' جنيه — ' + category + '. إجمالي النهارده: ' + money(total) + ' جنيه في ' + rows.length + ' عملية.' } }];
  }

  if (op === 'savings') {
    const amount = round2(input.amount);
    if (!isFinite(amount) || amount <= 0) return [{ json: { ok: false, error: 'amount لازم يكون رقم أكبر من صفر' } }];
    const note = NAME(input.note);
    const ins = parse(await hreq({ method: 'POST', url: base + '/rest/v1/savings_log', headers: Object.assign({}, HB, { Prefer: 'return=representation' }), body: { amount: amount, note: note, currency: 'EGP' }, json: true }));
    if (ins.st <= 0 || ins.st >= 300) return [{ json: { ok: false, error: 'فشل تسجيل التوفير: ' + errOf(ins) } }];
    const sr = parse(await hreq({ method: 'GET', url: base + '/rest/v1/savings_log?select=amount,saved_on', headers: HB, json: true }));
    const rows = (sr.st > 0 && sr.st < 300 && Array.isArray(sr.d)) ? sr.d : [];
    const mStart = monthStartCairo();
    const monthRows = rows.filter((x) => String(x.saved_on || '') >= mStart);
    return [{ json: { ok: true, saved: { amount: amount, note: note }, total_saved: round2(sumRows(rows)), month_saved: round2(sumRows(monthRows)), message: '💚 تمام! اتوفّر ' + money(amount) + ' جنيه. إجمالي التوفير: ' + money(sumRows(rows)) + ' جنيه (منهم ' + money(sumRows(monthRows)) + ' الشهر ده).' } }];
  }

  if (op === 'today') {
    const day = cairoToday();
    const r = parse(await hreq({ method: 'GET', url: base + '/rest/v1/expenses?select=id,amount,category,description,spent_on&spent_on=eq.' + day + '&order=created_at.desc', headers: HB, json: true }));
    if (r.st <= 0 || r.st >= 300) return [{ json: { ok: false, error: errOf(r) } }];
    const rows = Array.isArray(r.d) ? r.d : [];
    const total = round2(sumRows(rows));
    const list = rows.map((x) => ({ id: x.id, amount: Number(x.amount), category: x.category, description: x.description }));
    return [{ json: { ok: true, date: day, count: rows.length, total: total, expenses: list, summary: rows.length ? ('مصاريف النهارده: ' + money(total) + ' جنيه في ' + rows.length + ' عملية') : 'مفيش مصاريف مسجلة النهارده — يوم هادي 💚' } }];
  }

  if (op === 'week' || op === 'month') {
    const start = op === 'week' ? weekStartCairo() : monthStartCairo();
    const end = cairoToday();
    const r = parse(await hreq({ method: 'GET', url: base + '/rest/v1/expenses?select=id,amount,category,description,spent_on&spent_on=gte.' + start + '&spent_on=lte.' + end + '&order=spent_on.desc', headers: HB, json: true }));
    if (r.st <= 0 || r.st >= 300) return [{ json: { ok: false, error: errOf(r) } }];
    const rows = Array.isArray(r.d) ? r.d : [];
    const total = round2(sumRows(rows));
    const cats = byCat(rows).map((c) => ({ category: c.category, total: round2(c.total), count: c.count }));
    const label = op === 'week' ? ('مصاريف الأسبوع (من السبت ' + start + ' لحد ' + end + ')') : ('مصاريف الشهر (من ' + start + ' لحد ' + end + ')');
    const head = rows.length ? (label + ': ' + money(total) + ' جنيه في ' + rows.length + ' عملية') : (label + ': مفيش مصاريف مسجلة — تمام! 💚');
    const catLines = cats.map((c) => '• ' + c.category + ': ' + money(c.total) + ' جنيه (' + c.count + ')');
    return [{ json: { ok: true, from: start, to: end, count: rows.length, total: total, by_category: cats, recent: rows.slice(0, 10).map((x) => ({ id: x.id, amount: Number(x.amount), category: x.category, spent_on: x.spent_on })), summary: [head].concat(catLines).join('\n') } }];
  }

  if (op === 'delete') {
    const id = NAME(input.id);
    if (!id) return [{ json: { ok: false, error: 'id مطلوب — هات id من expense.today أو expense.week' } }];
    const del = parse(await hreq({ method: 'DELETE', url: base + '/rest/v1/expenses?id=eq.' + encodeURIComponent(id), headers: Object.assign({}, HB, { Prefer: 'return=representation' }), json: true }));
    if (del.st <= 0 || del.st >= 300) return [{ json: { ok: false, error: errOf(del) } }];
    const gone = Array.isArray(del.d) ? del.d : [];
    if (!gone.length) return [{ json: { ok: false, error: 'مفيش مصروف بالمعرّف ده: ' + id } }];
    const g = gone[0];
    return [{ json: { ok: true, deleted: { id: g.id, amount: Number(g.amount), category: g.category, spent_on: g.spent_on }, message: '🗑️ اتمسح: ' + money(g.amount) + ' جنيه — ' + String(g.category || '') + ' (' + String(g.spent_on || '') + ')' } }];
  }

  if (op === 'categories') {
    const r = parse(await hreq({ method: 'GET', url: base + '/rest/v1/expense_categories?select=name,is_active&order=created_at.asc', headers: HB, json: true }));
    if (r.st <= 0 || r.st >= 300) return [{ json: { ok: false, error: errOf(r) } }];
    const cats = (Array.isArray(r.d) ? r.d : []).map((x) => x.name);
    const er = parse(await hreq({ method: 'GET', url: base + '/rest/v1/expenses?select=category', headers: HB, json: true }));
    const used = {};
    if (er.st > 0 && er.st < 300 && Array.isArray(er.d)) for (const x of er.d) { const c = String(x.category || ''); used[c] = (used[c] || 0) + 1; }
    return [{ json: { ok: true, count: cats.length, categories: cats, usage: used } }];
  }

  return [{ json: { ok: false, error: 'عملية غير معروفة: "' + op + '". المتاح: log, savings, today, week, month, delete, categories' } }];
} catch (e) {
  return [{ json: { ok: false, error: 'خطأ غير متوقع: ' + String(e && e.message ? e.message : e).slice(0, 300) } }];
}

// OTHVM — expand the generic params object into the flat fields the workflow expects.
const j = $json || {};
let p = j.params;
if (typeof p === 'string') { try { p = JSON.parse(p); } catch (e) { p = {}; } }
if (!p || typeof p !== 'object' || Array.isArray(p)) p = {};
const out = Object.assign({}, p);
for (const k of ['operation', 'action', 'category']) {
  if (j[k] !== undefined && j[k] !== null && j[k] !== '') out[k] = j[k];
}
return [{ json: out }];
